-- ============================================================
-- Knowledge-check quizzes for "qa-leadership-academy".
-- Generated by scripts/content/build-quizzes.mjs — do not hand-edit;
-- edit scripts/content/qa-leadership-quizzes-a.mjs and regenerate. Run AFTER the course,
-- modules and schema exist. Idempotent: a module that already has a quiz
-- is skipped (no quizzes or attempts are ever deleted).
-- ============================================================

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 1),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Two of your testers are stuck the evening before a Northstar release, and with your expertise you could clear both blockers overnight. What is the strongest leadership move?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Clear both blockers yourself overnight so the release ships and the team is protected$qz$, false), ($qz$Pair briefly to unblock each tester and transfer the approach — or explicitly decide to step in just this once — rather than silently doing both alone$qz$, true), ($qz$Tell the testers to escalate to their squad leads and stay out of it entirely$qz$, false), ($qz$Push to slip the release, since a lead should never do hands-on work$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An executive tells you: "Great — from now on quality is your problem, own it end to end." What is the wisest response?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Accept it — a clear mandate to own quality is the authority QA has always needed$qz$, false), ($qz$Refuse any responsibility for quality until more testers are hired$qz$, false), ($qz$Decline sole ownership and propose an explicit split: QA owns strategy, risk-based coverage and the quality signal; engineering owns code quality; the business owns accepting risk$qz$, true), ($qz$Accept it quietly and rely on the existing regression suite to catch what developers miss$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Production defects are rising and the board asks QA to "increase test coverage". Investigation shows most escaped defects come from billing and integration changes QA only sees after code-complete. What is the strongest response?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Add regression tests across the whole product and request another tester to run them$qz$, false), ($qz$Extend the manual regression pass so more of the escaping defects are caught before release$qz$, false), ($qz$Reframe from detection to prevention — get QA into refinement for the high-risk change types and add contract tests, catching defects at the cheapest point$qz$, true), ($qz$Report the current bug-find rate to reassure the board that testing is working hard$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You inherit Northstar's QA team; management is loudly demanding "more automation". In week one you feel pressure to launch an automation project. What is the best first move?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Diagnose first — investigate where risk actually escapes, talk to the team and stakeholders, and take one genuine low-risk quick win to build credibility$qz$, true), ($qz$Launch the automation initiative immediately to show impact and meet expectations$qz$, false), ($qz$Restructure the team so automation has a dedicated squad from day one$qz$, false), ($qz$Announce that automation is the wrong answer before you have gathered any evidence$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You join fast-growing, Series-B Northstar from a regulated healthcare firm where every release had a formal test plan and independent sign-off. What should shape your approach?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Introduce the formal test plans and mandatory sign-off that worked well before — rigour travels$qz$, false), ($qz$Strip out all process, since a Series-B company should simply move fast$qz$, false), ($qz$Apply uniform heavyweight gates everywhere to be safe until you understand the product$qz$, false), ($qz$Keep the principle of making risk visible but adapt the mechanism to Northstar's stage and cadence, concentrating heavier controls only where impact justifies it$qz$, true)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Whenever a tricky technical question arises, your team waits and asks you for the answer rather than reasoning it out. What does this indicate, and what should change?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$The team lacks skill — you should keep answering to maintain the quality bar$qz$, false), ($qz$You are being the answer rather than building the team's reasoning — respond with guiding questions and standards, stepping in directly only for high-risk, one-way-door decisions$qz$, true), ($qz$You should stop answering entirely and let them work it out, whatever the risk$qz$, false), ($qz$You should document every answer so they can look it up instead of asking$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 2),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The CTO has read about TMMi and says "let's get to Level 3 by year end". You believe a blanket ladder-climb is the wrong move here. What is the strongest response?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Agree and build a programme to move the whole function up to Level 3$qz$, false), ($qz$Diagnose each capability against risk and invest in the two or three areas genuinely costing speed and incidents, deliberately staying lean where risk is low$qz$, true), ($qz$Explain that maturity models are pointless and refuse to assess maturity at all$qz$, false), ($qz$Aim for Level 5 instead, since higher maturity is always safer$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$As Northstar's first Head of QA you want an honest picture of where quality risk concentrates so you can prioritise investment. Which assessment frame fits best?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$A staged model that gives a single overall maturity level for the whole function$qz$, false), ($qz$A defect-count baseline, since bugs found is the clearest measure of quality$qz$, false), ($qz$A continuous, per-capability diagnostic scoring each area against its risk, so improvement can target specific weak areas$qz$, true), ($qz$Whichever model your previous employer used, to keep continuity$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar's 1,800-test Selenium suite is slow, roughly 25% flaky and distrusted. A tooling-only view concludes "replace the framework". Through the four-lens model, what is the flaw in that diagnosis?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Nothing — replacing a flaky framework is the direct fix for low trust$qz$, false), ($qz$The flaw is not migrating fast enough; the framework should be replaced this quarter$qz$, false), ($qz$The suite simply needs more tests added to improve its coverage$qz$, false), ($qz$It treats a culture/ownership problem — developers disown the suite so root causes go unfixed — as a technology problem; a new tool will be flaky again unless ownership changes$qz$, true)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A value-stream map shows a Northstar change takes 22 elapsed days but only about 4 days of actual work, with a late 5-day regression and repeated waits for a stable environment. What does the gap tell you?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$The system loses time and quality in queues and late, batched feedback — focus on compressing feedback loops and the late inspection, not making people work faster$qz$, true), ($qz$The testers are too slow; the fix is to speed up the touch-time activities$qz$, false), ($qz$The map is unreliable, because real processes never have that much waiting$qz$, false), ($qz$The regression is the sole problem; halving it will roughly halve the lead time$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar speeds its 5-day regression down to 3 days, but overall release lead time barely improves because changes now spend the saved time waiting for a stable environment. What does this prove?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$The regression cut was too small; cutting it further will finally move lead time$qz$, false), ($qz$The regression was not the true constraint — relieving it did not raise throughput; the governing constraint is the environment, and effort should move there$qz$, true), ($qz$The environment is fine; the team just needs to work through the waits faster$qz$, false), ($qz$Lead time is not a useful measure of whether an improvement worked$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Your matrix shows all of Northstar's CI and automation capability rests on one engineer who is near burnout, and there is no in-house performance testing (a spiky, occasional need). How should you close each gap?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Hire two automation engineers and one full-time performance tester$qz$, false), ($qz$Contract out the automation to remove the bus factor, and hire a permanent performance specialist$qz$, false), ($qz$Accept both gaps for now, since neither is causing an incident today$qz$, false), ($qz$Build a second person for the automation bus factor (you cannot contract away a retained-skill single point of failure), and borrow performance capability when it spikes$qz$, true)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 3),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A QA leader proposes a full "one embedded tester per squad" model for a six-person team covering Northstar's four squads, citing a famous tech company's structure. What is the strongest objection?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Embedded testers are always worse than a centralised team, so the model is wrong$qz$, false), ($qz$The model is copied rather than derived from Northstar's own risk profile and budget — six people spread one-per-squad cannot also cover performance, security and accessibility$qz$, true), ($qz$The famous company is larger, so Northstar should first hire more testers to match the model$qz$, false), ($qz$Nothing — matching a proven big-tech model is the safest choice$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar's centralised QA is pulled in at code-complete and blamed for the 5-day regression. The CTO returns from a conference wanting a big-tech "squads, chapters and guilds" model rolled out wholesale next quarter. What is the best move?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Roll out the literal model wholesale to satisfy the CTO$qz$, false), ($qz$Keep the centralised model unchanged, since reorganising never fixes anything$qz$, false), ($qz$Adopt the underlying idea — early involvement plus consistent standards — as a hybrid you can actually staff, embedding where risk is highest with a lightweight guild and a review point$qz$, true), ($qz$Fully embed all six testers into squads and disband any central function$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A load-related incident just happened and the CTO says "hire a performance tester". Performance-testing demand at Northstar is occasional, not continuous. What is the strongest response?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Hire the full-time performance tester as requested, to be safe$qz$, false), ($qz$Ignore performance testing; the incident was probably a one-off$qz$, false), ($qz$Train existing testers in load-test basics and contract a specialist for short bursts — spiky demand does not justify a permanent role$qz$, true), ($qz$Reassign the automation engineer to own performance testing permanently$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$On Northstar's skills matrix, CI/CD and UI automation score 3 for Dan and 0–1 for everyone else, and Dan owns a distrusted flaky suite while nearing burnout. What is the most urgent finding?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$The team simply needs training across the board to raise every score$qz$, false), ($qz$Dan should be promoted to reward his sole ownership of automation$qz$, false), ($qz$The scores are too low, so the proficiency scale must be miscalibrated$qz$, false), ($qz$A key-person risk (bus factor of one) — the whole automation and CI capability would leave with Dan — which outranks the general thinness elsewhere$qz$, true)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Tom (Head of Product) asks you to move Dan onto Mobile to "add automation there". The matrix shows Dan is the only person above level 1 on CI/CD and UI automation. What does the matrix tell you?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Moving Dan doesn't add automation to Mobile — it removes the org's entire automation and CI capability; develop a second person and stabilise the suite before any such move$qz$, true), ($qz$It's a simple reallocation — move Dan and let Mobile benefit$qz$, false), ($qz$Hire a contractor to run the flaky suite while Dan moves to Mobile$qz$, false), ($qz$Refuse any change to Dan's role permanently$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You have budget for exactly one QA hire. Web wants an accessibility specialist (real legal exposure), the API squad wants an SDET for the B2B SLAs, and payments needs deeper domain expertise. What is the best allocation?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Hire the accessibility specialist, since legal exposure is the most serious risk$qz$, false), ($qz$Hire the SDET — it reduces the SLA-linked risk and scales the whole team's testing — grow payments domain depth in-house, and buy periodic accessibility audits$qz$, true), ($qz$Split the one hire's time across all three needs so nothing is left uncovered$qz$, false), ($qz$Delay hiring until you can afford all three roles$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 4),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Your team is strong on automation but weak on cross-squad exploratory breadth and on representing quality to stakeholders. A brilliant automation specialist interviews superbly. Why should you hesitate?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Don't hesitate — a superb candidate should always be hired when you find one$qz$, false), ($qz$The specialist reinforces an existing strength and leaves the real gap open; anchor the decision to the written role definition, not to an off-target candidate's brilliance$qz$, true), ($qz$Hesitate only because their salary expectations may be high$qz$, false), ($qz$Redefine the role around the specialist's strengths so you can hire them$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Your job description lists eleven "essential" requirements, six of them tools. Applications are plentiful but the shortlist is weak, and a strong four-year candidate never applied. What is the most likely cause and fix?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$The salary is too low; raise it to attract stronger candidates$qz$, false), ($qz$There aren't enough good testers in the market; wait longer$qz$, false), ($qz$Add more essential requirements to raise the bar and filter harder$qz$, false), ($qz$The inflated, tool-heavy essentials attract keyword-matchers while strong, less-confident candidates self-deselect; cut to four to six genuine capabilities and move tools to desirables$qz$, true)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Two managers screen the same forty CVs and produce almost entirely different shortlists — one full of familiar tools and employers, the other full of candidates describing outcomes and decisions. What should you introduce?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$A shared, role-derived scorecard that scores each CV capability by capability, so screeners converge on the same evidence-based shortlist$qz$, true), ($qz$Let the more experienced manager's shortlist stand$qz$, false), ($qz$Interview everyone on both shortlists to avoid missing anyone$qz$, false), ($qz$Screen faster next time so gut instinct becomes more consistent$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A four-person panel each has a friendly, free-flowing conversation with every candidate, then meets and picks the one "everyone liked best". Why is this unreliable, and what single change helps most?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$It's fine — consensus that everyone liked someone is strong signal$qz$, false), ($qz$Add more interviewers so more perspectives are gathered$qz$, false), ($qz$Unstructured chats are dominated by rapport and confirmation bias and aren't comparable; assign defined capabilities to stages with core questions and score independently before discussing$qz$, true), ($qz$Shorten the interviews so first impressions matter less$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$For a mostly exploratory, stakeholder-facing senior QA role, how should you assess a candidate's technical capability?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Run a coding gauntlet and a definitions quiz, to be rigorous$qz$, false), ($qz$Reject any candidate who hasn't used your exact automation stack$qz$, false), ($qz$Put a real testing problem in front of them (e.g. "how would you test our payment flow, and where are you most worried?") and assess how they reason, matching depth to the role$qz$, true), ($qz$Skip technical assessment entirely, since the role is exploratory$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Candidate B (four years) doesn't know your legacy billing service's quirks but reasons cleanly to the key risk and communicates superbly; Candidate A (ten years) reasons well but communicates poorly — and communication is the gap the role exists to close. Who fits, and why?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Candidate A — ten years of experience outweighs a communication weakness$qz$, false), ($qz$Candidate B — the knowledge gap is coachable while her reasoning and communication match the role's defined gap; hire foundational reasoning and coach the knowledge$qz$, true), ($qz$Neither — reopen the search for someone with both deep tool knowledge and strong communication$qz$, false), ($qz$Whichever candidate the most senior interviewer preferred$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 5),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The CTO asks for "a proper test strategy" and clearly expects a long document, but your honest assessment is that a one-page set of choices would change more behaviour. What is the strongest response?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Write the comprehensive 40-page document to demonstrate rigour$qz$, false), ($qz$Refuse to write anything until the team is bigger$qz$, false), ($qz$Deliver the one-page strategy of real choices as the strategy itself, offering a longer document only for audiences that genuinely need the detail$qz$, true), ($qz$Copy a heavyweight template from a regulated employer and change the dates$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which of the following best indicates that you actually have a QA strategy rather than a wish list?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Every product area has a documented test approach of equal thoroughness$qz$, false), ($qz$You can name a few areas you have deliberately chosen not to cover to the same depth this year, and defend why that trade-off is acceptable$qz$, true), ($qz$The document covers every test level and type comprehensively$qz$, false), ($qz$The strategy lists all the tools the team will adopt$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$In the same week Northstar ships a misaligned button on the marketing site and an intermittent defect that occasionally charges a customer without granting access. A defect-count view calls them "two bugs". Why should the strategy treat them completely differently?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$They're equally important; both are defects that should be fixed with equal urgency$qz$, false), ($qz$The button should be fixed first, because visual defects damage the brand most$qz$, false), ($qz$They carry vastly different business risk — the payment defect threatens revenue, trust and an SLA — so effort should concentrate where business impact is high and consciously accept low-impact risk elsewhere$qz$, true), ($qz$Both should be logged and left, since neither blocks the release$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A QA lead proposes the objective "increase automated test coverage to 80% this quarter". What is weak about it as a strategic objective, and how would you improve it?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Nothing — 80% coverage is a clear, measurable and ambitious goal$qz$, false), ($qz$The target is too low; aim for 100% coverage$qz$, false), ($qz$Coverage is fine as a goal, but the deadline should be a full year$qz$, false), ($qz$It's an activity/vanity target — coverage can rise while incidents don't fall; name the business outcome (e.g. reduce escaped defects in high-risk areas) and treat automation as a leading activity$qz$, true)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar's main safety net is a large, slow, flaky end-to-end UI suite, and most of what it checks is business logic and input validation. A stakeholder asks QA to "add more end-to-end tests" to cut escaped defects. Why is that the wrong strategic move, and what should the strategy do instead?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Add the end-to-end tests as asked, to close the escaped-defect gap$qz$, false), ($qz$Rebalance the levels — push logic checks down to developer-owned unit and contract tests, shrink the E2E suite to high-value journeys, and reserve QA for exploratory work on risky areas$qz$, true), ($qz$Delete the end-to-end suite entirely and rely on unit tests alone$qz$, false), ($qz$Keep the suite as-is and add an engineer to maintain it$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Leadership is pushing for more automated tests, but Northstar's shared staging is so unstable that failures routinely turn out to be environment problems rather than real defects. What should the strategy prioritise, and why?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Add the automated tests now; the environment can be fixed later$qz$, false), ($qz$Abandon automation and rely on manual testing until staging improves$qz$, false), ($qz$Build a full production replica for every environment, to be safe$qz$, false), ($qz$Stabilise or isolate the environment first — test results are only as trustworthy as the environment they run in, so it usually has higher return than new tests$qz$, true)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 6),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A tracker shows a "high severity" crash on an internal admin page used by two staff, and a "medium severity" rounding error in the customer billing calculation. A tester argues the crash must be fixed first because it is higher severity. Why challenge that ordering?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$The tester is right — always fix the highest-severity item first$qz$, false), ($qz$Severity is not risk — read both across the impact dimensions: the admin crash is near-zero on business, customer and compliance impact, while the billing error carries real business, compliance and reputational impact, so it is the higher product risk$qz$, true), ($qz$Fix both simultaneously, since they are both open defects$qz$, false), ($qz$The billing error is only "medium", so it can safely wait until next sprint$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Two release risks score the same overall on the matrix: one is high-probability/low-impact, the other low-probability/high-impact. A colleague says "they're equal, treat them the same". Why is that the wrong conclusion?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$They are equal, so treating them the same is correct$qz$, false), ($qz$Always prioritise the high-probability one, as it is more likely to occur$qz$, false), ($qz$An equal overall score hides that they need different responses — reduce likelihood (or accept) the first; reduce impact via flags, monitoring or a tested rollback for the second$qz$, true), ($qz$Combine them into a single aggregate score to simplify the decision$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A QA lead runs a "risk workshop" but does most of the talking, presents a pre-made risk list, and asks the room to confirm the scores. It's efficient and everyone agrees. Why should the lead be worried rather than pleased?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$There is nothing to worry about — efficiency and consensus are the goal$qz$, false), ($qz$Easy agreement means the room's distributed knowledge was never pooled and no independent judgement surfaced; switch to silent generation, capture without debating, and score independently before revealing$qz$, true), ($qz$The only problem is that the meeting ran too long; shorten it next time$qz$, false), ($qz$The lead should have made all the scoring decisions alone, to save time$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Under deadline pressure Northstar's test plan must be cut, and a tester proposes trimming a fixed percentage off every area equally "to be fair". Why is an equal cut the wrong instinct?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$It's the fairest approach, so it is the right one$qz$, false), ($qz$Cutting anything is negligent; the deadline should always slip instead$qz$, false), ($qz$Cut the high-risk areas most, since they take the longest to test$qz$, false), ($qz$An equal cut removes as much coverage from the high-impact areas as from the safe ones; protect or deepen the top-band risks, take the cuts from low-risk areas, and record what is no longer tested$qz$, true)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The night before release, Tom asks point-blank: "Just tell me — do we ship or not?" You have a mixed picture: two untested critical scenarios, an intermittent payment bug, 90% of regression green. Why resist a bare yes/no?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Just say "yes" — 90% passing is good enough to ship$qz$, false), ($qz$Just say "no" — untested critical scenarios mean it isn't safe$qz$, false), ($qz$A bare yes/no makes QA own a decision whose business consequences it can't weigh; give a recommendation inside a structured picture — good news, ranked residual risk, costed options including a conditional-go — so the accountable owner decides and owns it$qz$, true), ($qz$Refuse to comment until every critical scenario has been tested$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You deliver a clear conditional-go recommendation and Tom responds, "Great — so QA's signing off that it's safe to ship?", visibly trying to hand you ownership of the decision. What is the best response?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Agree — if you're confident in the recommendation, signing off is reasonable$qz$, false), ($qz$Restate that QA's assessment and recommendation stand, but accepting that level of residual risk against the date is Tom's call since he owns the consequences — and you'll record what he accepts$qz$, true), ($qz$Withdraw the recommendation to avoid any appearance of owning the decision$qz$, false), ($qz$Say "it's safe" to keep the conversation moving and hit the date$qz$, false)) as v(t, c) returning question_id)
select 1;

